/** Aktueller Name einer (evtl. alten) Übung. */
fun migrateName(name: String): String = RENAMED_EXERCISES[name] ?: name

// ---------- Körpergewicht & Kalorien ----------

/** Ein Wiege-Eintrag. */
data class WeightEntry(val time: Long, val kg: Double)

/*
 * Kalorienschätzung nach der MET-Methode (Metabolic Equivalent of Task):
 *   kcal = MET × Körpergewicht in kg × Dauer in Stunden
 * MET-Werte nach dem „Compendium of Physical Activities“ (gerundet). Das ist eine Schätzung –
 * Intensität, Pausen und individuelle Unterschiede kann die Formel nicht erfassen.
 */
private val CARDIO_MET = mapOf(
    "Laufband" to 8.0,
    "Laufband Gehen mit Steigung" to 6.0,
    "Laufen (draußen)" to 9.0,
    "Gehen" to 3.5,
    "Wandern" to 6.0,
    "Crosstrainer" to 5.0,
    "Fahrradergometer" to 6.8,
    "Spinning" to 8.5,
    "Radfahren (draußen)" to 7.5,
    "Air Bike" to 10.0,
    "Rudergerät" to 7.0,
    "Ski-Ergometer" to 7.0,
    "Stepper" to 9.0,
    "Seilspringen" to 11.0,
    "Schwimmen" to 7.0,
    "HIIT" to 8.0,
    "Boxen (Sandsack)" to 7.5,
    "Battle Ropes" to 8.0
)

/** MET für Cardio-Übungen; unbekannte Cardio-Übungen bekommen einen mittleren Wert. */
fun cardioMet(name: String): Double = CARDIO_MET[name] ?: 7.0

/** Krafttraining mit Pausen: „Gewichtheben, kräftig“ ≈ 5 MET. */
const val STRENGTH_MET = 5.0

/** Geschätzte Zeit pro Kraft-Satz inkl. Pause, wenn es keine echte Trainingsdauer gibt (freies Training). */
const val MINUTES_PER_SET = 2.5


